mapper.select:
SELECT r.id, b.id AS building_id, b.building_name, f.floor_number, r.room_number, r.room_type, r.capacity, r.gender_restriction, r.education_level_scope, r.resident_scope, b.gender_restriction AS building_gender_restriction, b.education_level_scope AS building_education_level_scope, b.resident_scope AS building_resident_scope, r.operational_status, r.state_version, r.remark, COALESCE(bed_stats.bed_count, 0) AS bed_count, COALESCE(bed_stats.enabled_bed_count, 0) AS enabled_bed_count, COALESCE(bed_stats.disabled_bed_count, 0) AS disabled_bed_count, COALESCE(bed_stats.maintenance_bed_count, 0) AS maintenance_bed_count, COALESCE(occupancy.active_resident_count, 0) AS active_resident_count, COALESCE(occupancy.confirmed_bed_count, 0) AS confirmed_bed_count, COALESCE(occupancy.unconfirmed_bed_count, 0) AS unconfirmed_bed_count, GREATEST(r.capacity - COALESCE(occupancy.active_resident_count, 0), 0) AS remaining_capacity FROM room r JOIN dormitory_floor f ON f.id = r.floor_id JOIN dormitory_building b ON b.id = f.building_id LEFT JOIN ( SELECT bed.room_id, SUM(CASE WHEN bed.operational_status <> 'RETIRED' THEN 1 ELSE 0 END) AS bed_count, SUM(CASE WHEN bed.operational_status = 'ENABLED' THEN 1 ELSE 0 END) AS enabled_bed_count, SUM(CASE WHEN bed.operational_status = 'DISABLED' THEN 1 ELSE 0 END) AS disabled_bed_count, SUM(CASE WHEN bed.operational_status = 'MAINTENANCE' THEN 1 ELSE 0 END) AS maintenance_bed_count FROM bed GROUP BY bed.room_id ) bed_stats ON bed_stats.room_id = r.id LEFT JOIN ( SELECT ra.room_id, COUNT(*) AS active_resident_count, SUM(CASE WHEN ra.bed_id IS NOT NULL THEN 1 ELSE 0 END) AS confirmed_bed_count, SUM(CASE WHEN ra.bed_id IS NULL THEN 1 ELSE 0 END) AS unconfirmed_bed_count FROM room_assignment ra WHERE ra.assignment_status = 'ACTIVE' GROUP BY ra.room_id ) occupancy ON occupancy.room_id = r.id
b.id = #{buildingId}
AND r.gender_restriction = #{gender}
ORDER BY b.building_code, f.floor_number, r.room_number
